#!/usr/bin/env python3
"""
Generate explicit template instantiations for Jacobi2D GPU functions.
Run this script to regenerate JacobiKernelInstantiations.cu when adding
new block sizes or function variants.
"""

# Block sizes to instantiate
# Naive supports all sizes, BlockWise variants require at least 8
NAIVE_BLOCK_SIZES = [1, 4, 8, 16, 32, 64, 128, 256]
BLOCKWISE_BLOCK_SIZES = [1, 4, 8, 16, 32, 64, 128, 256]

HEADER = '''// Auto-generated file - do not edit directly
// Generated by generate_jacobi_instantiations.py

#include "JacobiKernel.cuh"
#include "definition/vector/MxVector.hpp"
#include "JacobiKernelMxVectorNaive.cuh"
#include "JacobiKernelMxVectorBlockWise.cuh"
#include "JacobiKernelMxVectorBlockWiseRequant.cuh"
'''

def generate_type_aliases():
    """Generate type aliases for each block size."""
    lines = ["// Type aliases for different block sizes"]
    for bs in sorted(set(NAIVE_BLOCK_SIZES + BLOCKWISE_BLOCK_SIZES)):
        lines.append(f"using GPUVector{bs} = mx::vector::MxVector<BlockDims<{bs}>, unsigned char, fp8::E4M3Type,")
        lines.append(f"                                        GPUArithmeticNaive, MaximumFractionalQuantization>;")
        lines.append("")
    return "\n".join(lines)


def generate_naive_instantiations():
    """Generate instantiations for Jacobi2DGPUMxVectorNaive."""
    lines = ["// Explicit template instantiations for Jacobi2DGPUMxVectorNaive"]
    for bs in NAIVE_BLOCK_SIZES:
        lines.append(f"template GPUVector{bs} Jacobi2DGPUMxVectorNaive<GPUVector{bs}>(")
        lines.append(f"    const GPUVector{bs}&, const GPUVector{bs}&, uint32_t, uint32_t);")
        lines.append("")
    return "\n".join(lines)


def generate_blockwise_instantiations():
    """Generate instantiations for Jacobi2DGPUMxVectorBlockWise."""
    lines = ["// Explicit template instantiations for Jacobi2DGPUMxVectorBlockWise"]
    for bs in BLOCKWISE_BLOCK_SIZES:
        lines.append(f"template GPUVector{bs} Jacobi2DGPUMxVectorBlockWise<GPUVector{bs}>(")
        lines.append(f"    const GPUVector{bs}&, const GPUVector{bs}&, uint32_t, uint32_t);")
        lines.append("")
    return "\n".join(lines)


def generate_blockwise_requant_instantiations():
    """Generate instantiations for Jacobi2DGPUMxVectorBlockWiseRequant."""
    lines = ["// Explicit template instantiations for Jacobi2DGPUMxVectorBlockWiseRequant"]
    for bs in BLOCKWISE_BLOCK_SIZES:
        lines.append(f"template GPUVector{bs} Jacobi2DGPUMxVectorBlockWiseRequant<GPUVector{bs}>(")
        lines.append(f"    const GPUVector{bs}&, const GPUVector{bs}&, uint32_t, uint32_t);")
        lines.append("")
    return "\n".join(lines)


def generate_naive_context_instantiations():
    """Generate instantiations for MxVector Naive Setup/Compute/Teardown."""
    lines = [
        "// =============================================================================",
        "// Explicit instantiations for Setup/Compute/Teardown functions (MxVector Naive)",
        "// =============================================================================",
        "",
    ]
    for bs in NAIVE_BLOCK_SIZES:
        vec = f"GPUVector{bs}"
        lines.append(f"template void Jacobi2DMxVectorNaiveSetup<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorNaiveContext<{vec}>&, const {vec}&, const {vec}&, uint32_t);")
        lines.append(f"template void Jacobi2DMxVectorNaiveCompute<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorNaiveContext<{vec}>&, uint32_t);")
        lines.append(f"template {vec} Jacobi2DMxVectorNaiveTeardown<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorNaiveContext<{vec}>&);")
        lines.append("")
    return "\n".join(lines)


def generate_blockwise_context_instantiations():
    """Generate instantiations for MxVector BlockWise Setup/Compute/Teardown."""
    lines = [
        "// =============================================================================",
        "// Explicit instantiations for Setup/Compute/Teardown functions (MxVector BlockWise)",
        "// =============================================================================",
        "",
    ]
    for bs in BLOCKWISE_BLOCK_SIZES:
        vec = f"GPUVector{bs}"
        lines.append(f"template void Jacobi2DMxVectorBlockWiseSetup<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseContext<{vec}>&, const {vec}&, const {vec}&, uint32_t);")
        lines.append(f"template void Jacobi2DMxVectorBlockWiseCompute<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseContext<{vec}>&, uint32_t);")
        lines.append(f"template {vec} Jacobi2DMxVectorBlockWiseTeardown<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseContext<{vec}>&);")
        lines.append("")
    return "\n".join(lines)


def generate_blockwise_requant_context_instantiations():
    """Generate instantiations for MxVector BlockWise Requant Setup/Compute/Teardown."""
    lines = [
        "// =============================================================================",
        "// Explicit instantiations for Setup/Compute/Teardown functions (MxVector BlockWise Requant)",
        "// =============================================================================",
        "",
    ]
    for bs in BLOCKWISE_BLOCK_SIZES:
        vec = f"GPUVector{bs}"
        lines.append(f"template void Jacobi2DMxVectorBlockWiseRequantSetup<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseRequantContext<{vec}>&, const {vec}&, const {vec}&, uint32_t);")
        lines.append(f"template void Jacobi2DMxVectorBlockWiseRequantCompute<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseRequantContext<{vec}>&, uint32_t);")
        lines.append(f"template {vec} Jacobi2DMxVectorBlockWiseRequantTeardown<{vec}>(")
        lines.append(f"    Jacobi2DMxVectorBlockWiseRequantContext<{vec}>&);")
        lines.append("")
    return "\n".join(lines)


def main():
    output = HEADER
    output += generate_type_aliases()
    output += "\n"
    output += generate_naive_instantiations()
    output += generate_blockwise_instantiations()
    output += generate_blockwise_requant_instantiations()
    output += generate_naive_context_instantiations()
    output += generate_blockwise_context_instantiations()
    output += generate_blockwise_requant_context_instantiations()
    
    # Write to file
    import os
    script_dir = os.path.dirname(os.path.abspath(__file__))
    output_path = os.path.join(script_dir, "JacobiKernelInstantiations.cu")
    
    with open(output_path, "w") as f:
        f.write(output)
    
    print(f"Generated {output_path}")
    print(f"  - Naive: {len(NAIVE_BLOCK_SIZES)} block sizes")
    print(f"  - BlockWise: {len(BLOCKWISE_BLOCK_SIZES)} block sizes")
    print(f"  - BlockWise Requant: {len(BLOCKWISE_BLOCK_SIZES)} block sizes")
    print(f"  - Context functions for all variants")


if __name__ == "__main__":
    main()


